pub fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

pub fn all_digits(s: String) -> bool {
    // Vacuously true for the empty string.
    for ch in s.chars() {
        if !is_ascii_digit(ch) {
            return false;
        }
    }
    true
}